+SET LOCAL lock_timeout = '10s';
+SET LOCAL statement_timeout = '10min';
+DROP FUNCTION IF EXISTS event_operation_reassign_raci(BIGINT,BIGINT,BIGINT,UUID,BIGINT,TEXT,BIGINT,BIGINT,TEXT,TEXT);
